import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AboutPage.css";

const AboutP = [
  {
    id: 1,
    title: "Material 1",
    description: "Descrição breve dos módulos",
    author: "Guilherme Moreira",
    views: 5,
    date: "há 21 horas",
    image: "",
  },
  {
    id: 2,
    title: "Material 2",
    description: "Descrição breve do material 2",
    author: "Guilherme Moreira",
    views: 0,
    date: "há 21 horas",
    image: "",
  },
];

const AboutPage = () => {
  const [courseViews, setCourseViews] = useState(AboutP);
  const navigate = useNavigate();

  useEffect(() => {
    const savedViews = JSON.parse(localStorage.getItem('courseViews') || '[]');
    if (savedViews.length > 0) {
      setCourseViews(savedViews);
    }
  }, []);

  const handleClickCourse = (id) => {
    setCourseViews((prevAboutP) => {
      const updatedAboutP = prevAboutP.map((course) =>
        course.id === id
          ? { ...course, views: course.views + 1 }
          : course
      );
      localStorage.setItem('courseViews', JSON.stringify(updatedAboutP));
      return updatedAboutP;
    });

    navigate(`/AboutP/${id}`);
  };

  return (
    <div className="AboutP-page">
      <div className="name_apresentation">
        <div className="logo">
          <span className="idctec">IDC<b>TEC</b></span>
        </div>
        <div className="subtitle">
          <span>Integração Digital e <br/> Capacitação Tecnológica</span>
        </div>
      </div>
      <div className="AboutP-container">
        {courseViews.map((course) => (
          <div
            key={course.id}
            className="course-card"
            onClick={() => handleClickCourse(course.id)}
          >
            <div className="course-image">
              {course.image ? (
                <img src={course.image} alt={course.title} />
              ) : (
                <div className="placeholder-icon">
                  <span>📘</span>
                </div>
              )}
            </div>

            <div className="course-info">
              <h2 className="course-title">{course.title}</h2>
              <p className="course-description">{course.description}</p>
              <p className="course-author">{course.author}</p>
              <div className="course-stats">
                <span>{course.views} visualizações</span>
                <span>{course.date}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AboutPage;
